-- 1) 테이블 생성 (이미 있으면 skip)
DECLARE
  v_cnt NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_cnt FROM USER_TABLES WHERE TABLE_NAME = 'SCM_ADM_PROGRAM';
  IF v_cnt = 0 THEN
    EXECUTE IMMEDIATE 'CREATE TABLE SCM_MGR.SCM_ADM_PROGRAM (
      PROGRAM_ID         VARCHAR2(50)  NOT NULL,
      PROGRAM_NAME       VARCHAR2(200) NOT NULL,
      PROGRAM_PATH       VARCHAR2(500) NOT NULL,
      CLASS_NAME         VARCHAR2(500) NOT NULL,
      USE_YN             CHAR(1)       DEFAULT ''Y''      NOT NULL,
      REGT_USER_ID       VARCHAR2(100),
      CREATED_BY         VARCHAR2(100) DEFAULT ''system'' NOT NULL,
      CREATION_DATE      DATE          DEFAULT SYSDATE    NOT NULL,
      LAST_UPDATED_BY    VARCHAR2(100) DEFAULT ''system'' NOT NULL,
      LAST_UPDATE_DATE   DATE          DEFAULT SYSDATE    NOT NULL,
      CONSTRAINT PK_SCM_ADM_PROGRAM PRIMARY KEY (PROGRAM_ID)
    )';
  END IF;
END;
/

-- 2) 기존 데이터 삭제 (재실행 안전)
DELETE FROM SCM_MGR.SCM_ADM_PROGRAM;

-- 3) 사내 데이터 INSERT (405 rows)

COMMIT;

-- 4) GRANT (BE 사용계정)
GRANT SELECT, INSERT, UPDATE, DELETE ON SCM_MGR.SCM_ADM_PROGRAM TO SCMD_APP;

-- 5) SP 재컴파일 (SCM_ADM_PROGRAM 의존 INVALID → VALID)
ALTER PROCEDURE SCM_MGR.P_SYS0015_GET_PROGRAM_LIST_M COMPILE;
ALTER PROCEDURE SCM_MGR.P_SYS0015_SAVE_PROGRAM_M COMPILE;

-- 6) 검증
SELECT COUNT(*) AS total_rows FROM SCM_MGR.SCM_ADM_PROGRAM;  -- 예상: 405
SELECT OBJECT_NAME, STATUS FROM USER_OBJECTS
 WHERE OBJECT_NAME IN ('SCM_ADM_PROGRAM','P_SYS0015_GET_PROGRAM_LIST_M','P_SYS0015_SAVE_PROGRAM_M');
